custom_css:
/* 雨声留白 · reference reconstruction, modular external textures and ornaments. */

:root{--pr-ink:#315b82;--pr-base:#eef7ff;}
#sheld{background:var(--pr-base)!important;box-shadow:none!important;backdrop-filter:none!important;}
#chat{padding:0!important;gap:0!important;container-type:inline-size;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/surface.webp') center top/100% auto repeat-y!important;}
#chat .mes{position:relative;isolation:isolate;box-sizing:border-box;display:grid!important;grid-template-columns:minmax(0,48%) minmax(0,1fr);column-gap:12px;row-gap:16px;align-items:center!important;width:100%!important;max-width:720px!important;min-width:0!important;margin:0 auto 24px!important;padding:24px 20px 80px!important;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;color:var(--pr-ink)!important;backdrop-filter:none!important;}
#chat .mes>.mes_block{display:contents!important;}
#chat .mes::before,#chat .mes::after,#chat .mes>.mes_block::before,#chat .mes>.mes_block::after{content:'';position:absolute;pointer-events:none;background-repeat:no-repeat;background-size:contain;z-index:-1;}
#chat .mes .mesAvatarWrapper{grid-column:1;grid-row:1;position:relative!important;display:flex!important;flex-wrap:wrap;justify-content:space-around;align-items:center;align-content:start;gap:12px 2px;width:auto!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:0!important;}
#chat .mes .avatar{box-sizing:border-box;position:relative;flex:0 0 100%;width:100%!important;max-width:none!important;height:auto!important;aspect-ratio:1;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background:none!important;}
#chat .mes .avatar img{width:100%!important;height:100%!important;object-fit:cover!important;object-position:center 35%;border-radius:inherit!important;box-shadow:none!important;}
#chat .mes .mesIDDisplay,#chat .mes .mes_timer,#chat .mes .tokenCounterDisplay{position:static!important;width:auto!important;margin:0!important;padding:0!important;line-height:1.4!important;font-size:9px!important;color:var(--pr-ink)!important;opacity:.75;}
#chat .mes .ch_name{grid-column:2;grid-row:1;align-self:center;position:relative;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:stretch!important;gap:12px;width:100%!important;min-width:0!important;margin:0!important;padding:0!important;background:none!important;}
#chat .mes .ch_name>.flex1{display:flex!important;flex:none!important;justify-content:center;align-items:center;min-width:0;text-align:center;}
#chat .mes .name_text{display:block;max-width:100%;font-size:21px!important;line-height:1.4;font-weight:400;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .timestamp{font-size:9px;}
#chat .mes .mes_buttons{position:relative!important;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:2px!important;width:100%!important;max-width:100%!important;min-width:0!important;margin:0!important;padding:4px 0!important;float:none!important;opacity:1!important;}
#chat .mes .mes_button{box-sizing:border-box;flex:0 0 auto;min-width:20px;min-height:26px;padding:2px!important;color:var(--pr-ink)!important;filter:none!important;text-shadow:none!important;}
#chat .mes .extraMesButtons{flex-wrap:wrap;justify-content:center;gap:4px;max-width:100%;flex-basis:100%;}
#chat .mes .mes_text{grid-column:1/-1;position:relative;box-sizing:border-box;width:100%!important;min-width:0!important;margin:0!important;padding:24px 15px 35px!important;min-height:200px;line-height:1.9!important;color:var(--pr-ink)!important;overflow-wrap:anywhere;}
#chat .mes .mes_text p{margin:.4em 0 .9em;}
#chat .mes .mes_text img,#chat .mes .mes_text video{max-width:100%;height:auto;}
#chat .mes .mes_text pre{max-width:100%;overflow-x:auto;}
#chat .mes .mes_text table{display:block;max-width:100%;overflow-x:auto;}
#chat .mes>.for_checkbox{position:absolute;left:4px;top:4px;}
#chat .mes>.swipe_left{position:absolute;left:10px;bottom:14px;z-index:3;}
#chat .mes>.swipe_right{position:absolute;right:10px;bottom:14px;z-index:3;}
#chat .mes .swipes-counter{color:var(--pr-ink);}
#top-bar{background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/surface.webp') center top/100% auto!important;box-shadow:none!important;border:0!important;}
#top-settings-holder{gap:0!important;}
#top-settings-holder>.drawer{min-width:0!important;flex:1 1 0;}
#top-settings-holder .drawer-toggle{display:flex;align-items:center;justify-content:center;min-height:38px;}
#top-settings-holder .drawer-icon{color:var(--pr-ink)!important;filter:none!important;opacity:1!important;font-size:22px!important;}
#send_form{position:relative;isolation:isolate;box-sizing:border-box;gap:8px!important;min-height:64px;padding:12px 18px!important;border:0!important;box-shadow:none!important;border-radius:0!important;background:var(--pr-base) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/surface.webp') center bottom/100% auto!important;}
#send_form::before{content:'';position:absolute;inset:5px;z-index:-1;pointer-events:none;background:rgba(255,255,255,.85);border-radius:20px;}
#send_textarea{background:transparent!important;color:var(--pr-ink)!important;border:0!important;box-shadow:none!important;min-height:36px;}
#send_textarea::placeholder{color:var(--pr-ink);opacity:.7;}
#send_form :is(i,.fa-solid,.fa-regular){color:var(--pr-ink)!important;filter:none!important;}
@media(min-width:700px){#chat .mes .name_text{font-size:25px!important;}#chat .mes .mes_text{font-size:18px;}}

#chat .mes{grid-template-columns:minmax(0,54%) minmax(0,1fr);padding:68px 15px 26px!important;gap:18px 12px;}
#chat .mes::before{left:0;top:-10px;width:79%;height:clamp(145px,42vw,240px);background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/umbrella.webp') left top/contain no-repeat;z-index:2;}
#chat .mes .avatar{border:6px solid white!important;border-bottom-width:18px!important;border-radius:1px!important;transform:rotate(-7deg);}
#chat .mes .mesAvatarWrapper{gap:16px 2px;padding-left:5px!important;}
#chat .mes .ch_name{position:static;align-self:end;padding:0 3px 38px!important;}
#chat .mes .ch_name>.flex1{background:rgba(255,255,255,.8);padding:14px 0 18px;clip-path:polygon(0 7%,96% 0,100% 91%,4% 100%);}
#chat .mes .ch_name::before{content:'';position:absolute;top:8px;right:7px;width:22%;height:clamp(145px,42vw,240px);background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/chime.webp') center top/contain no-repeat;pointer-events:none;}
#chat .mes .mes_buttons{position:absolute!important;right:3px;top:clamp(280px,76vw,470px);width:36px!important;max-width:36px!important;flex-direction:column!important;gap:9px!important;z-index:3;}
#chat .mes .mes_button{width:34px;height:34px;border:1px solid #fff;border-radius:50%;background:rgba(255,255,255,.72);color:#6c9fc2!important;box-shadow:0 2px 5px #b8d9eb44;}
#chat .mes .extraMesButtons{background:rgba(246,252,255,.95);border-radius:16px;}
#chat .mes .mes_text{width:calc(100% - 32px)!important;min-height:265px;padding:28px 23px 100px!important;border:1px solid #fff;border-radius:22px;background:rgba(248,252,255,.78);}
#chat .mes .mes_text::after{content:'';position:absolute;left:-8px;right:-8px;bottom:-8px;height:140px;pointer-events:none;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/rain-bottom.webp') center bottom/100% auto no-repeat;opacity:.9;mask-image:linear-gradient(transparent,#000 28%,#000 90%,transparent);}
#chat .mes .mes_text::before{content:'';position:absolute;inset:0;pointer-events:none;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/rain-left.webp') left top/24px auto repeat-y,url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/rain-right.webp') right top/24px auto repeat-y;opacity:.5;}
#send_form::before{background:rgba(248,253,255,.76);border:1px solid white;box-shadow:inset 0 0 12px #fff8;border-radius:30px;}
#top-bar,#send_form{backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px);}

#top-settings-holder>.drawer:nth-child(1) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(1) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(2) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(2) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(3) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(3) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(4) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(4) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(5) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(5) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(6) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-2.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(6) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(7) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-3.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(7) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(8) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-4.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(8) .drawer-icon::before{opacity:0!important;}
#top-settings-holder>.drawer:nth-child(9) .drawer-icon{width:27px!important;height:29px!important;font-size:0!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-1.webp') center/contain no-repeat!important;}#top-settings-holder>.drawer:nth-child(9) .drawer-icon::before{opacity:0!important;}
#send_but{background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v2/rain/icon-2.webp') center/contain no-repeat!important;font-size:0!important;}#send_but::before{opacity:0;}
#chat .mes .mes_buttons .extraMesButtons{position:absolute;right:40px;top:0;width:76px;max-width:76px;flex-basis:auto;padding:6px;background:rgba(248,252,255,.98);border:1px solid #c5d9e7;border-radius:12px;z-index:5;}
html,body,body *{scrollbar-width:none!important;scrollbar-gutter:auto!important;}
body::-webkit-scrollbar,body *::-webkit-scrollbar,html::-webkit-scrollbar{width:0!important;height:0!important;display:none!important;}
#chat{padding-inline:0!important;border-inline:0!important;box-sizing:border-box!important;background-attachment:scroll!important;}
#chat .mes .mes_buttons{overflow:visible!important;max-height:none!important;}

#chat .mes>:not(.mesAvatarWrapper):not(.mes_block):not(.for_checkbox):not(.swipe_left):not(.swipe_right),
#chat .mes>.mes_block>:not(.ch_name):not(.mes_text){grid-column:1/-1!important;min-width:0;max-width:100%;box-sizing:border-box;}
#chat .mes .mes_text{padding-left:8px!important;padding-right:8px!important;}

#chat .mes{padding-left:9px!important;padding-right:9px!important;}#chat .mes .mes_text{padding-left:12px!important;padding-right:12px!important;}
/* Painted controls: no CSS-drawn borders, no native scrollbar gutters. */
:root{--scrollbar-width:0px;--scrollbarWidth:0px;}
*,*::before,*::after{scrollbar-width:none!important;scrollbar-gutter:auto!important;}
*::-webkit-scrollbar,*::-webkit-scrollbar-track,*::-webkit-scrollbar-thumb,*::-webkit-scrollbar-corner{display:none!important;width:0!important;height:0!important;border:0!important;}
#chat{width:100%!important;padding-inline:0!important;margin-inline:0!important;border-inline:0!important;}
#chat .mes .mes_text{width:100%!important;max-width:100%!important;padding-inline:8px!important;margin-inline:0!important;box-sizing:border-box!important;}
#chat .mes .mes_buttons{display:flex!important;flex-direction:row!important;flex-wrap:wrap!important;align-items:center!important;justify-content:center!important;gap:5px!important;padding:5px 0!important;border:0!important;border-radius:0!important;box-shadow:none!important;background:transparent!important;overflow:visible!important;}
#chat .mes .mes_buttons::after{display:none!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons),#chat .mes .extraMesButtons>.mes_button{box-sizing:border-box!important;flex:0 0 36px!important;width:36px!important;min-width:36px!important;max-width:36px!important;height:36px!important;min-height:36px!important;margin:0!important;padding:0!important;float:none!important;position:relative!important;inset:auto!important;transform:none!important;line-height:36px!important;text-align:center!important;border:0!important;border-radius:0!important;box-shadow:none!important;filter:none!important;text-shadow:none!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons){background:var(--painted-action,url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/0.webp')) center/contain no-repeat!important;font-size:0!important;color:transparent!important;opacity:1!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons)::before,#chat .mes .mes_buttons>:not(.extraMesButtons)::after{opacity:0!important;}
#chat .mes .mes_buttons>:not(.extraMesButtons)>:is(img,svg,i,span){visibility:hidden!important;}
#chat .mes .mes_buttons .extraMesButtons{position:absolute!important;top:100%!important;right:0!important;left:auto!important;width:160px!important;max-width:160px!important;flex-basis:auto!important;gap:6px!important;padding:6px!important;z-index:9;}
#send_form :is(#options_button,#extensionsMenuButton){width:36px!important;height:38px!important;min-width:36px!important;flex:0 0 36px!important;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;font-size:0!important;filter:none!important;}
#send_form #options_button{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/7.webp')!important;}
#send_form #extensionsMenuButton{background-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/8.webp')!important;}
#send_form :is(#options_button,#extensionsMenuButton)::before,#send_form :is(#options_button,#extensionsMenuButton)::after{display:none!important;}
#send_form :is(#options_button,#extensionsMenuButton)>*{visibility:hidden!important;}
@media(max-width:700px){#sheld{width:100%!important;max-width:100%!important;left:0!important;right:0!important;margin-inline:0!important;border-inline:0!important;padding-inline:0!important;}#chat .mes{max-width:100%!important;}}

#chat .mes .mes_buttons>:is(.extraMesButtonsHint){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/0.webp');}
#chat .mes .mes_buttons>:is(.mes_bookmark,.mes_create_bookmark,.fa-flag){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/1.webp');}
#chat .mes .mes_buttons>:is(.mes_narrate,.fa-music,.fa-volume-high,.fa-bullhorn){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/2.webp');}
#chat .mes .mes_buttons>:is([title*="熊"],[title*="酒馆助手"],[title*="Tavern Helper"],[class*="tavern_helper"]){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/3.webp');}
#chat .mes .mes_buttons>:is(.mes_edit,.fa-pencil,.fa-pen){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/4.webp');}
#chat .mes .mes_buttons>:is(.mes_copy,.fa-layer-group,.fa-copy){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/5.webp');}
#chat .mes .mes_buttons>:is(.fa-chart-simple,.fa-chart-column,.fa-chart-bar,[title*="统计"],[class*="token_counter"]){--painted-action:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/6.webp');}
#chat .mes .mes_buttons{position:relative!important;inset:auto!important;width:100%!important;min-width:0!important;max-width:100%!important;}
#chat .mes .mes_text{padding-inline:10px!important;}

#chat{background:#eef7ff!important;}
#chat .mes{background:rgba(246,252,255,.88)!important;padding-bottom:125px!important;row-gap:16px!important;}
#chat .mes>.mes_block::before{content:'';inset:0 0 auto!important;height:auto!important;aspect-ratio:1!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/surface.webp') center top/100% auto no-repeat!important;mask-image:linear-gradient(#000 0%,rgba(0,0,0,.6) 45%,transparent 100%)!important;z-index:-2!important;}
#chat .mes .mes_text{background:none!important;border:0!important;border-radius:0!important;padding-bottom:20px!important;min-height:150px!important;}
#chat .mes .mes_text::before,#chat .mes .mes_text::after{display:none!important;}
#chat .mes::after{content:'';left:0;right:0;bottom:0;height:120px;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/poetic-v3/rain/rain-bottom.webp') center bottom/100% auto no-repeat;mask-image:linear-gradient(transparent,#000 30%);z-index:-1;}
#chat .mes .avatar{border:0!important;border-radius:4px!important;transform:rotate(-4deg)!important;}
#chat .mes .avatar img{clip-path:inset(7% round 3px)!important;}
#chat .mes .avatar::after{content:'';position:absolute;inset:0;pointer-events:none;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/portrait.webp') center/contain no-repeat;}
#chat .mes .ch_name>.flex1{clip-path:none!important;background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/painted-controls/rain/name.webp') center/contain no-repeat!important;padding:16px 5px!important;min-height:58px!important;}
